import java.io.*;
import java.util.*;

public class Main {
    // smallest cyclic rotation of the decimal string; it identifies the equivalence class
    static String canonical(long value) {
        String s = Long.toString(value), best = s;
        for (int i = 1; i < s.length(); i++) {
            String r = s.substring(i) + s.substring(0, i);
            if (r.compareTo(best) < 0) best = r;
        }
        return best;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        HashMap<String, Long> counts = new HashMap<>();
        for (int i = 0; i < n; i++) {
            in.nextToken();
            counts.merge(canonical((long) in.nval), 1L, Long::sum);
        }
        long ans = 0;
        for (long c : counts.values()) ans += c * (c - 1) / 2;
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

// smallest cyclic rotation of the decimal string; it identifies the equivalence class
func canonical(value int64) string {
	s := strconv.FormatInt(value, 10)
	best := s
	for i := 1; i < len(s); i++ {
		if r := s[i:] + s[:i]; r < best {
			best = r
		}
	}
	return best
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	counts := map[string]int64{}
	for i := 0; i < n; i++ {
		var v int64
		fmt.Fscan(reader, &v)
		counts[canonical(v)]++
	}
	var ans int64
	for _, c := range counts {
		ans += c * (c - 1) / 2
	}
	fmt.Println(ans)
}
